// Extrair nomes da mensagem recebida
const message = $input.item.json.body.message || $input.item.json.message || '';

if (!message) {
  return [{
    json: {
      success: false,
      error: 'Nenhuma mensagem fornecida',
      message: message
    }
  }];
}

// Lista de palavras que não são nomes
const STOP_WORDS = [
  'o', 'a', 'os', 'as', 'um', 'uma', 'whatsapp', 'email',
  'senhor', 'senhora', 'dr', 'dra', 'doutor', 'doutora'
];

// Função para extrair nomes
function extractNames(text) {
  const names = [];

  // Padrão 1: "falar com [Nome]" ou similar
  const contextPatterns = [
    /(?:falar com|entregar para|enviar para|contatar|ligar para|mensagem para|agendar com|reunião com|encontrar com|conversar com)\s+([A-ZÀÁÂÃÄÅÈÉÊËÌÍÎÏÒÓÔÕÖÙÚÛÜÇ][a-zàáâãäåçèéêëìíîïñòóôõöùúûüý]+(?:\s+[A-ZÀÁÂÃÄÅÈÉÊËÌÍÎÏÒÓÔÕÖÙÚÛÜÇ][a-zàáâãäåçèéêëìíîïñòóôõöùúûüý]+)*)/gi
  ];

  contextPatterns.forEach(pattern => {
    const matches = text.matchAll(pattern);
    for (const match of matches) {
      if (match[1]) {
        names.push(match[1].trim());
      }
    }
  });

  // Padrão 2: Nomes próprios (palavras com maiúscula)
  const namePattern = /\b([A-ZÀÁÂÃÄÅÈÉÊËÌÍÎÏÒÓÔÕÖÙÚÛÜÇ][a-zàáâãäåçèéêëìíîïñòóôõöùúûüý]{2,}(?:\s+(?:da|de|do|das|dos|e)\s+)?(?:[A-ZÀÁÂÃÄÅÈÉÊËÌÍÎÏÒÓÔÕÖÙÚÛÜÇ][a-zàáâãäåçèéêëìíîïñòóôõöùúûüý]+)*)\b/g;
  const matches = text.matchAll(namePattern);

  for (const match of matches) {
    const name = match[1].trim();
    const nameLower = name.toLowerCase();

    // Filtrar stop words e nomes muito curtos
    if (name.length >= 3 && !STOP_WORDS.includes(nameLower)) {
      const words = name.split(/\s+/);
      // Aceitar se tem 2+ palavras ou não é início comum de frase
      if (words.length >= 2) {
        names.push(name);
      }
    }
  }

  // Remover duplicatas
  return [...new Set(names)];
}

const extractedNames = extractNames(message);

return [{
  json: {
    success: true,
    message: message,
    extractedNames: extractedNames,
    totalNamesFound: extractedNames.length
  }
}];

// Preparar cada nome para busca individual
const names = $input.item.json.extractedNames || [];
const message = $input.item.json.message;

const output = names.map(name => ({
  json: {
    searchName: name,
    originalMessage: message,
    // Variações do nome para busca
    nameVariations: [
      name,
      name.toLowerCase(),
      name.toUpperCase(),
      // Primeiro nome
      name.split(' ')[0],
      // Nome completo sem acentos (para busca flexível)
      name.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    ]
  }
}));

return output;

// Consolidar resultados da busca
const allResults = [];

// Processar todos os itens de entrada
for (const item of $input.all()) {
  if (item.json.nome_completo) {
    allResults.push({
      nome: item.json.nome_completo,
      email: item.json.email,
      telefone: item.json.telefone,
      id: item.json.id,
      searchedName: item.json.searchName || 'N/A',
      // Adicione outros campos relevantes do seu banco
    });
  }
}

// Remover duplicatas por ID
const uniqueResults = {};
allResults.forEach(result => {
  if (!uniqueResults[result.id]) {
    uniqueResults[result.id] = result;
  }
});

return [{
  json: {
    success: true,
    totalFound: Object.keys(uniqueResults).length,
    pessoas: Object.values(uniqueResults),
    originalMessage: $input.first().json.originalMessage
  }
}];
